const WdIconRef *wd_icon_find(const WdIconRef *table, size_t count, const char *name) {
    size_t i;
    for (i = 0; i < count; i++) {
        if (strcmp(table[i].name, name) == 0) {
            return &table[i];
        }
    }
    return NULL;
}

int wd_icon_decode(int slot, uint32_t *out) {
    uint32_t i;
    int n = 0;
    if (slot < 0 || slot >= WD_ICON_SLOTS || out == NULL) {
        return -1;
    }
    for (i = wd_icon_off[slot]; i < wd_icon_off[slot + 1]; i += 2) {
        uint32_t count = wd_icon_blob[i];
        uint32_t value = wd_icon_blob[i + 1];
        while (count--) {
            out[n++] = value;
        }
    }
    return n == WD_ICON_PX ? 0 : -1;
}
